def compare_clocks(a, b):
    a_ahead = b_ahead = False
    for node in a.keys() | b.keys():          # every node in either clock; a missing node counts as 0
        mine, theirs = a.get(node, 0), b.get(node, 0)
        if mine > theirs:
            a_ahead = True
        elif mine < theirs:
            b_ahead = True
    if a_ahead and b_ahead:
        return "concurrent"
    if a_ahead:
        return "after"
    if b_ahead:
        return "before"
    return "equal"


def merge_clocks(a, b):
    return {node: max(a.get(node, 0), b.get(node, 0)) for node in a.keys() | b.keys()}
